() => {
  const links = Array.from(document.querySelectorAll('a'));
  const tasks = [];
  const seen = new Set();
  for (const a of links) {
    const href = a.href || '';
    const m = href.match(/TECH-\d+/);
    if (!m) continue;
    const id = m[0];
    if (seen.has(id)) continue;
    seen.add(id);
    const text = (a.innerText || a.getAttribute('aria-label') || '').replace(/\s+/g, ' ').trim();
    tasks.push({ id, text: text.slice(0, 200), href });
  }
  return { title: document.title, count: tasks.length, tasks };
}

